shaders.glsl:
// Liquid Metatron — a breathing sacred-geometry lattice smeared into itself by
// accumulated time-offset trails (feedback look, no framebuffer required).
#define TAU 6.28318530718

mat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

float segment(vec2 p, vec2 a, vec2 b){
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// Distance to the metatron figure, folded into a 6-fold wedge so one wedge of
// primitives draws the whole mandala.
float figure(vec2 p, float t){
    float s = 1.0 + 0.06 * sin(t * 0.7);
    p /= s;
    p *= rot(t * 0.12);

    float a = atan(p.y, p.x);
    float r = length(p);
    a = mod(a + TAU / 12.0, TAU / 6.0) - TAU / 12.0;
    vec2 q = vec2(cos(a), sin(a)) * r;

    float d = 1e4;
    d = min(d, abs(length(q) - 0.16));
    d = min(d, abs(length(q - vec2(0.42, 0.0)) - 0.16));
    d = min(d, abs(length(q - vec2(0.84, 0.0)) - 0.16));
    d = min(d, segment(q, vec2(0.0, 0.0), vec2(0.84, 0.0)));
    d = min(d, segment(q, vec2(0.42, 0.0), vec2(0.21, 0.3637)));
    d = min(d, segment(q, vec2(0.84, 0.0), vec2(0.42, 0.7275)));
    d = min(d, segment(q, vec2(0.42, 0.0), vec2(0.42, 0.7275)));
    return d * s;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;

    vec3 col = vec3(0.0);
    for (int i = 0; i < 7; i++){
        float fi = float(i);
        float ti = t - fi * 0.055;
        vec2 p = uv * rot(-fi * 0.02) * (1.0 + fi * 0.012);
        float d = figure(p, ti);
        float glow = 0.0011 / (d * d + 0.00025);
        // Hue drifts with radius and a gentle directional tilt. Deliberately no
        // atan() term here: its branch cut would show as a hard seam on -x.
        float hue = 0.09 * ti + fi * 0.04 + length(uv) * 0.85
                  + dot(uv, vec2(0.09, 0.05));
        col += palette(hue) * glow * exp(-fi * 0.55);
    }
    col *= 0.38;

    col += palette(0.2 * t + 0.5) * 0.006 / (dot(uv, uv) + 0.04);
    col *= 1.0 - 0.55 * smoothstep(0.5, 1.5, length(uv));
    col = col / (1.0 + col);
    col = pow(col, vec3(0.85));
    fragColor = vec4(col, 1.0);
}

// Hexad Bloom — a flower-of-life lattice receding down a twelve-slice
// kaleidoscopic tunnel, thin neon rings dissolving into the dark.
#define TAU 6.28318530718

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

// Distance to the nearest flower-of-life ring on a hexagonal lattice.
float flower(vec2 p, float r){
    vec2 s = vec2(1.0, 1.7320508);
    vec2 a = mod(p, s) - s * 0.5;
    vec2 b = mod(p + s * 0.5, s) - s * 0.5;
    return abs(min(length(a), length(b)) - r);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;

    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // Twelve-slice kaleidoscopic fold, slowly precessing.
    a = abs(mod(a + t * 0.05, TAU / 6.0) - TAU / 12.0);

    // Tunnel: dz runs as 1/r so the lattice recedes to a vanishing point.
    float dz = 2.7 / (r + 0.16);
    float depth = dz + t * 1.2;

    // Ring thickness is corrected by the tunnel's own derivative so rings stay a
    // constant width on screen instead of aliasing into spokes near the centre.
    float k = (r + 0.16) * (r + 0.16) / 2.7;

    vec3 col = vec3(0.0);
    for (int i = 0; i < 2; i++){
        float fi = float(i);
        vec2 tp = vec2(a * 5.0, depth) * (1.0 + fi * 0.5) + vec2(fi * 0.7, 0.0);
        float ds = flower(tp, 0.36) * k;
        col += palette(0.06 * t - depth * 0.13 + fi * 0.22)
             * (0.00035 / (ds * ds + 0.00012)) * (1.0 - 0.45 * fi);
    }

    // Fog on the spatial part of the depth only, so it does not crawl with time.
    col *= exp(-dz * 0.17);
    col *= smoothstep(0.0, 0.28, r);
    col *= 1.0 - 0.35 * smoothstep(0.7, 1.6, r);
    col = col / (1.0 + col);
    col = pow(col, vec3(0.9));
    fragColor = vec4(col, 1.0);
}

// Moiré Yantra — three counter-rotating ring systems beating against each other
// into moiré fringes, with a pair of yantra triangles orbiting a bindu.
#define TAU 6.28318530718

mat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

// Distance to an equilateral triangle outline.
float triOutline(vec2 p, float r){
    const float k = 1.7320508;
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0 * r, 0.0);
    return abs(-length(p) * sign(p.y));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;
    vec3 col = vec3(0.0);

    float m = 1.0;
    for (int i = 0; i < 3; i++){
        float fi = float(i);
        vec2 p = uv * rot(t * 0.07 * (fi + 1.0))
               + vec2(sin(t * 0.23 + fi), cos(t * 0.19 + fi)) * 0.06;
        m *= sin(length(p) * (26.0 + fi * 3.5) - t * 1.2 + fi * 1.7);
    }
    col += palette(0.1 * t + length(uv) * 0.5) * pow(abs(m), 6.0) * 1.4;

    for (int i = 0; i < 2; i++){
        float fi = float(i);
        vec2 p = uv * rot(t * 0.15 * (fi * 2.0 - 1.0) + fi * 3.14159);
        float d = triOutline(p, 0.62 + 0.03 * sin(t * 0.9 + fi * 2.0));
        col += palette(0.14 * t + 0.4 + fi * 0.25) * (0.0022 / (d * d + 0.0006));
    }

    col += vec3(1.0, 0.6, 1.0) * 0.015 / (dot(uv, uv) + 0.02);
    col *= 1.0 - 0.6 * smoothstep(0.6, 1.55, length(uv));
    col = col / (1.0 + col);
    col = pow(col, vec3(0.88));
    fragColor = vec4(col, 1.0);
}
